import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Codex History and Model Cache Investigation","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-05-26-codex-history-investigation.md","filePath":"plans/2026-05-26-codex-history-investigation.md"}'),i={name:"plans/2026-05-26-codex-history-investigation.md"};function n(d,e,r,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="codex-history-and-model-cache-investigation" tabindex="-1">Codex History and Model Cache Investigation <a class="header-anchor" href="#codex-history-and-model-cache-investigation" aria-label="Permalink to &quot;Codex History and Model Cache Investigation&quot;">​</a></h1><p><strong>Date:</strong> 2026-05-26 <strong>Status:</strong> Decision recorded <strong>Scope:</strong> Codex CLI generated <code>history.jsonl</code> and <code>models_cache.json</code></p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use a diagnostics-only backend surface for now. Do not add a product Codex Sessions page yet.</p><p>Local inspection shows <code>history.jsonl</code> rows with <code>session_id</code>, <code>ts</code>, and <code>text</code>. The session id and timestamp are useful, but <code>text</code> is prompt content and must be treated as sensitive. There is not enough non-sensitive metadata yet to provide a useful history UI comparable to Claude Code transcripts without exposing prompt bodies or inventing unsupported semantics.</p><p>Local inspection shows <code>models_cache.json</code> root keys including <code>fetched_at</code>, <code>etag</code>, <code>client_version</code>, and <code>models</code>. This is useful for diagnostics, but the raw model cache is generated data and should not be exposed wholesale.</p><h2 id="implemented-surface" tabindex="-1">Implemented Surface <a class="header-anchor" href="#implemented-surface" aria-label="Permalink to &quot;Implemented Surface&quot;">​</a></h2><p>Add a read-only Codex diagnostics endpoint that summarizes:</p><ul><li>History file existence, size, row counts, observed keys, timestamp range, session counts, and hashed session identifiers.</li><li>Model cache existence, size, root keys, fetch/client metadata, cache validator presence, model container shape, and model count.</li></ul><p>The endpoint intentionally omits:</p><ul><li>Raw history rows.</li><li>Prompt text.</li><li>Raw session ids.</li><li>Raw model cache JSON.</li><li>Cache validator values.</li></ul><h2 id="follow-up-criteria" tabindex="-1">Follow-Up Criteria <a class="header-anchor" href="#follow-up-criteria" aria-label="Permalink to &quot;Follow-Up Criteria&quot;">​</a></h2><p>A product Codex Sessions page should wait until Codex exposes stable, non-sensitive local metadata for project paths, message roles, model choices per session, and safe summaries. Until then, Claude-only transcript pages should remain Claude-only and Codex should use diagnostics-only history/cache reporting.</p>',13)])])}const m=o(i,[["render",n]]);export{u as __pageData,m as default};
